    ReportsController_get: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                id: number;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        scheduleId: number;
                        /** @enum {string} */
                        level: "INTERMEDIATE" | "ADVANCED";
                        candidate: {
                            fullName: string;
                            email: string;
                            phone: string | null;
                            workExperienceYears: number;
                        };
                        advisor: string;
                        template: {
                            name: string;
                            version: number;
                            durationMinutes: number;
                            passPercent: number;
                        };
                        attempt: {
                            /** Format: date-time */
                            startedAt: string;
                            /** Format: date-time */
                            submittedAt: string;
                            /**
                             * @description CANDIDATE pressed Submit; TIMEOUT means the server submitted at the deadline
                             * @enum {string}
                             */
                            submitReason: "CANDIDATE" | "TIMEOUT";
                        };
                        result: {
                            totalMarks: number;
                            obtainedMarks: number;
                            /** @description 0 to 100, two decimals */
                            percentage: number;
                            passed: boolean;
                        };
                        topics: {
                            topic: string;
                            questions: number;
                            answered: number;
                            correct: number;
                            totalMarks: number;
                            obtainedMarks: number;
                            items: {
                                questionVersionId: number;
                                /** @description The question’s code, such as ETATA1. For staff only */
                                code: string;
                                /** @description Position inside its topic, in the order the candidate saw */
                                number: number;
                                /** @enum {string} */
                                status: "correct" | "wrong" | "blank";
                                marks: number;
                                totalMarks: number;
                                statementMd: string;
                                /** @description The code the question refers to, one entry per language. Null when the question has none */
                                codeStubs: {
                                    language: string;
                                    label: string;
                                    code: string;
                                }[] | null;
                                options: {
                                    id: number;
                                    textMd: string;
                                    isCorrect: boolean;
                                    /** @description The option the candidate picked */
                                    chosen: boolean;
                                }[];
                            }[];
                        }[];
                    };
                };
            };
        };
    };
